import{K as r,a as i,c as l,b as t,k as n,q as h,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerPoint 内容结构与汇报逻辑","description":"从受众和决策目标规划演示稿，用结论、证据和行动建立五页汇报，安排标题、备注、附录与演讲时间。","frontmatter":{"title":"PowerPoint 内容结构与汇报逻辑","description":"从受众和决策目标规划演示稿，用结论、证据和行动建立五页汇报，安排标题、备注、附录与演讲时间。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · PowerPoint 演示制作","summary":"从受众和决策目标规划演示稿，用结论、证据和行动建立五页汇报，安排标题、备注、附录与演讲时间。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":false,"next":{"text":"PowerPoint 主题、母版与版式","link":"/tools/office/powerpoint/layout"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"PowerPoint 主题、母版与版式","link":"/tools/office/powerpoint/layout"}},"headers":[],"relativePath":"tools/office/powerpoint/story.md","filePath":"tools/office/powerpoint/story.md"}'),s={name:"tools/office/powerpoint/story.md"},k=Object.assign(s,{setup(c){const a={path:"/tools/office/powerpoint/story",app:"PowerPoint",title:"先用五页标题讲清一件事",steps:[{tab:"开始",command:"新建幻灯片",setting:"五页：结论 / 证据 / 问题 / 行动 / 决策",anchor:"walkthrough-1"},{tab:"视图",command:"大纲视图",setting:"只看标题与正文层级；删除重复内容",anchor:"walkthrough-2"},{tab:"幻灯片放映",command:"排练计时",setting:"按实际时长讲述；记录每页耗时",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=t("h1",{id:"powerpoint-内容结构与汇报逻辑",tabindex:"-1"},[n("PowerPoint 内容结构与汇报逻辑 "),t("a",{class:"header-anchor",href:"#powerpoint-内容结构与汇报逻辑","aria-label":'Permalink to "PowerPoint 内容结构与汇报逻辑"'},"​")],-1)),e[1]||(e[1]=t("p",null,"好的演示稿帮助听众理解问题并作出决定。开始时先写内容结构，再选择模板；把 Word 报告逐段复制进幻灯片，通常会得到字太多、重点不清的结果。",-1)),h(o,{guide:a}),e[2]||(e[2]=d('<h2 id="goal" tabindex="-1">明确受众与任务 <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;明确受众与任务 {#goal}&quot;">​</a></h2><p>先用一句话回答“听众看完后要知道什么或做什么”。项目周报可能需要确认下周资源，培训需要学员能完成一个动作，方案评审需要选择某条路径。面向不熟悉背景的人，应补足基本概念；面向项目团队，可把更多时间留给变化和风险。</p><p>再确定演示时长、现场还是线上、是否会脱离讲解单独阅读。脱离讲解的阅读稿需要更完整的说明，现场投影稿需要更清楚的视觉层级，两者可以共享内容但不必完全相同。</p><h2 id="outline" tabindex="-1">先写五页骨架 <a class="header-anchor" href="#outline" aria-label="Permalink to &quot;先写五页骨架 {#outline}&quot;">​</a></h2><p>以<a href="/tools/office/excel/project">Excel 月报</a>为数据来源：</p><table tabindex="0"><thead><tr><th>页码</th><th>标题示例</th><th>本页任务</th></tr></thead><tbody><tr><td>1</td><td>10 月完成订单金额为 3160 元</td><td>先给结论和统计范围</td></tr><tr><td>2</td><td>运营部门贡献 2440 元，技术部门贡献 720 元</td><td>展示部门比较</td></tr><tr><td>3</td><td>待处理订单金额 900 元需跟进</td><td>说明尚未完成的工作</td></tr><tr><td>4</td><td>下月优先处理待办并规范录入</td><td>提出行动和责任人</td></tr><tr><td>5</td><td>请确认跟进人和月报截止时间</td><td>明确需要的决定</td></tr></tbody></table><p>这里的“完成订单金额”不能随意改称收入或利润，练习数据没有提供会计确认和成本信息。每页标题最好表达发现或问题，避免五页都叫“数据分析”。</p><h2 id="hierarchy" tabindex="-1">每页安排信息层次 <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;每页安排信息层次 {#hierarchy}&quot;">​</a></h2><p>通常从一句主结论、一个核心图表、少量必要说明开始。说明写清时间、单位、口径和例外；长段背景移到备注或附录。需要多个观点时，检查它们是否真的服务于同一个问题，否则拆成两页。</p><p>正文保留可读字号，删减重复表达，不能为了塞进更多文字不断缩小字号。培训材料可以分步骤演示，同一页只显示当前需要的内容；操作菜单和关键数值仍应清楚可见。</p><h2 id="notes" tabindex="-1">备注、附录与证据 <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;备注、附录与证据 {#notes}&quot;">​</a></h2><p>备注用于记录讲解顺序、例子、转场和可能问题。现场无需逐字朗读页面文字，可在备注里写“先解释统计口径，再指出部门差异”。引用的数据和外部材料应标记来源；练习数据要明确写“虚构示例”。</p><p>附录放详细数据、补充推导和备选方案，在问答时按需进入。不要把影响主要结论的关键限制全部藏在附录，否则听众可能在未理解条件时作出决定。</p><h2 id="rehearse" tabindex="-1">排练与删减 <a class="header-anchor" href="#rehearse" aria-label="Permalink to &quot;排练与删减 {#rehearse}&quot;">​</a></h2><p>先按实际时长讲一遍，再根据超时位置调整。讲不完时优先删重复背景和次要案例，不单纯提高语速。每页停留时间应由内容复杂度决定，不能机械地规定所有页数一样。</p><p>在幻灯片浏览视图查看整体节奏：是否连续多页都是密集表格，是否缺少总结和行动，是否出现前面没解释的新缩写。把演示发给没有参与制作的人，看其能否说出主结论，是很有效的内容检查。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>先只写五页标题和每页一句说明，不加图片与动画。遮住正文，只看标题是否仍能串起完整故事。再给每页标注预计讲解时长，总计控制在你的实际演讲时间以内，留出问答余量。</p><p>下一步使用<a href="/tools/office/powerpoint/layout">母版与版式</a>统一视觉结构。</p><h2 id="walkthrough" tabindex="-1">图示跟做：先用五页标题讲清一件事 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：先用五页标题讲清一件事 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：只写标题先检查故事线 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：只写标题先检查故事线 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 新建幻灯片。</strong></p><p>新建演示文稿，用“开始 → 新建幻灯片”建立五页，按正文示例分别写结论、部门比较、待处理订单、下月行动和需确认事项。每个标题都要能独立表达意思，例如“十月已完成金额 3160 元”，不只写“数据分析”。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：检查是否脱离图表也能理解 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：检查是否脱离图表也能理解 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：视图 → 大纲视图。</strong></p><p>切到大纲视图，读一遍五个标题，检查是否自然从发现走到行动。大纲主要显示占位符里的文字，随意插入的文本框不一定包含在内，因此应使用标题和内容版式的占位符。没有支持主结论的段落移到附录或删除。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用一遍真实讲述验收结构 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用一遍真实讲述验收结构 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：幻灯片放映 → 排练计时。</strong></p><p>点击排练计时，按计划讲一遍。记录哪一页需要过多背景解释，优先拆清逻辑或缩减材料。保存计时后若现场不想自动翻页，要在放映设置中检查是否使用计时。讲完后听众应知道结论、依据和需要自己做的决定。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>3160 是虚构订单的已完成金额，不是利润或已确认收入。演示稿应沿用原数据指标名，不能为了标题简短改变业务含义。</p>',32))])}}});export{u as __pageData,k as default};
